'use strict';
// City filters are point attributes. They do not change the climate raster.
class CityMapOverlay{
 constructor(navigation,discovery,filters,getState,inspect){this.navigation=navigation;this.discovery=discovery;this.filters=filters;this.getState=getState;this.inspect=inspect;this.features=[];this.entries=new Map();this.popup=new maplibregl.Popup({closeButton:false,closeOnClick:false,offset:12});navigation.ready.then(()=>{this.install();this.refresh();});}
 install(){const map=this.navigation.map;if(map.getSource('city-filter-points'))return;map.addSource('city-filter-points',{type:'geojson',data:{type:'FeatureCollection',features:[]}});map.addLayer({id:'city-filter-points',type:'circle',source:'city-filter-points',paint:{'circle-radius':['interpolate',['linear'],['zoom'],0,2.5,4,4,8,7],'circle-color':['get','color'],'circle-stroke-color':['case',['get','unknown'],'#53637c','#ffffff'],'circle-stroke-width':1.5,'circle-opacity':['step',['zoom'],['case',['all',['!', ['get','unknown']],['>=',['get','population'],500000]],.9,0],3,['case',['all',['!', ['get','unknown']],['>=',['get','population'],100000]],.9,0],4.5,['case',['>=',['get','population'],100000],.9,0],5,.9]}});map.on('mousemove','city-filter-points',e=>{const feature=e.features?.[0],entry=feature&&this.entries.get(Number(feature.properties.id));if(!entry)return;const box=document.createElement('div');box.className='city-filter-popup';const heading=document.createElement('strong');heading.textContent=entry.name;box.append(heading);const line=t=>{const p=document.createElement('p');p.textContent=t;box.append(p);};line(entry.subtitle);line(`${Number(entry.score).toFixed(1)} / 10 · ${Number(entry.days).toFixed(1)} comfortable days/year`);const reasons=this.filters.reasons(entry);line(reasons.length?'Excluded from your filtered ranking':'Matches your city filters');if(reasons.length){const ul=document.createElement('ul');for(const text of reasons){const li=document.createElement('li');li.textContent=text;ul.append(li);}box.append(ul);}const n=this.filters.nomads.get(entry.place[0]),h=this.filters.homicide.get(entry.place[5]+'|'+this.filters.state.year);if(n)line(`Nomads ${n.score.toFixed(1)}/5 · $${Math.round(n.monthly_cost_usd).toLocaleString('en')}/month estimate`);if(h)line(`Country homicide: ${h.value.toFixed(1)}/100,000 · ${h.year}`);line('Click to inspect this city');const coords=feature.geometry.coordinates.slice();while(Math.abs(e.lngLat.lng-coords[0])>180)coords[0]+=e.lngLat.lng>coords[0]?360:-360;this.popup.setLngLat(coords).setDOMContent(box).addTo(map);});map.on('mouseleave','city-filter-points',()=>this.popup.remove());map.on('movestart',()=>this.popup.remove());}
 color(value){const m=this.navigation.meta,q=Math.max(0,Math.min(1,value/(this.getState().view==='days'?150:10)))*12,a=Math.min(11,Math.floor(q)),rgb=this.navigation.rgb;return '#'+rgb[a].map((c,i)=>Math.round(c+(rgb[a+1][i]-c)*(q-a)).toString(16).padStart(2,'0')).join('');}
 export(ctx,x,y,w,h,bounds){if(!this.features.length)return;const west=bounds[0][1],east=bounds[1][1],south=bounds[0][0],north=bounds[1][0];ctx.save();for(const f of this.features){const [lon,lat]=f.geometry.coordinates;if(lon<west||lon>east||lat<south||lat>north)continue;ctx.beginPath();ctx.arc(x+(lon-west)/(east-west)*w,y+(north-lat)/(north-south)*h,4.5,0,Math.PI*2);ctx.fillStyle=f.properties.color;ctx.fill();ctx.strokeStyle=f.properties.unknown?'#53637c':'#ffffff';ctx.lineWidth=1.5;ctx.stroke();}ctx.restore();}
 refresh(){const s=this.getState(),map=this.navigation.map;if(!this.navigation.loaded||!map.getSource('city-filter-points')||!s.scoreValues||s.busy)return;const enabled=document.getElementById('city-map-effect').value==='markers',active=this.filters.active,minimum=Number(document.getElementById('rank-population').value),signature=JSON.stringify([enabled,this.filters.signature,s.currentRegion,s.view,minimum]);if(this.lastSignature===signature&&this.lastScores===s.scoreValues&&this.lastDays===s.dayValues)return;this.lastSignature=signature;this.lastScores=s.scoreValues;this.lastDays=s.dayValues;this.popup.remove();this.entries.clear();let matched=0,excluded=0,unknown=0;const features=[];if(enabled&&active&&this.filters.ready)for(const e of this.discovery.entries){if(e.population<minimum||s.currentRegion!=='world'&&e.region!==s.currentRegion||e.distance>.75||!Number.isFinite(s.scoreValues[e.index])||!Number.isFinite(s.dayValues[e.index]))continue;const reasons=this.filters.reasons(e),missing=reasons.some(r=>r.includes('unavailable')),entry={...e,score:s.scoreValues[e.index],days:s.dayValues[e.index]};if(reasons.length)excluded++;else matched++;if(missing)unknown++;this.entries.set(e.place[0],entry);features.push({type:'Feature',geometry:{type:'Point',coordinates:[e.place[3],e.place[2]]},properties:{id:e.place[0],population:e.population,unknown:missing,excluded:!!reasons.length,color:missing?'#ffffff':reasons.length?'#69758a':this.color(s.view==='days'?entry.days:entry.score)}});}this.features=features;map.getSource('city-filter-points').setData({type:'FeatureCollection',features});document.getElementById('city-map-status').textContent=!active?'Enable a city filter to compare places.':!enabled?'City filters affect the ranking only.':`${matched.toLocaleString('en')} matching · ${excluded.toLocaleString('en')} excluded (${unknown.toLocaleString('en')} missing data). Gray: fails; white: unknown. Cities ≥${minimum.toLocaleString('en')} residents. Zoom in for smaller or unknown cities. Hover or tap a marker; weather colors stay unchanged.`;}
}
window.CityMapOverlay=CityMapOverlay;
